        let mut stmt = conn
            .prepare(
                "SELECT id, workflow, status, result, error, created_ms, updated_ms,
                        input, workflow_spec_json, resume_attempts, session_cwd
                 FROM tasks ORDER BY updated_ms DESC LIMIT ?1",
