            String,
            bool,
            Option<bridge_core::orch::UsageSnapshot>,
        )>,
        BridgeError,
    > {
        let conn = self.conn.lock().unwrap();
        let mut stmt = conn
            .prepare(
                "SELECT node_id, output, ok, usage_json FROM task_node_checkpoints WHERE task_id=?1",
            )
