                row.updated_ms = ts;
                Ok(true)
            }
            _ => Ok(false),
        }
    }

    async fn fail_batch_if_status(
        &self,
        id: &BatchId,
        expect: BatchStatus,
        error: &str,
        ts: i64,
    ) -> Result<bool, BridgeError> {
        let mut g = self.batches.lock().unwrap();
        match g.get_mut(id) {
            Some(row) if row.status == expect => {
                row.status = BatchStatus::Failed;
                row.error = Some(error.to_string());
                row.updated_ms = ts;
                Ok(true)
            }
            _ => Ok(false),
        }
    }

